533	Write $d$ for the dimension of the~$A$ matrices.
534	If the~$\{R_a\}$ matrices from \Cref{lem:projective-non-measurement} formed a projective sub-measurement,
535	then their total rank would be at most~$d$.
536	Even if this is not true,
537	the next lemma shows that we can still post-process them
538	to reduce their total rank to at most~$d$.
539	
540	\begin{lemma}[Rank reduction]\label{lem:projective-low-rank-sum}
541	There exists a set of projection matrices $\{Q_a\}$ such that
542	\begin{equation*}
543	A_a \ot I \approx_{12\sqrt{\zeta}} Q_a \ot I.
544	\end{equation*}
545	and
546	\begin{equation*}
547	Q:= \sum_a Q_a \leq (1+2\sqrt{\zeta}) \cdot I.
548	\end{equation*}
549	Furthermore,  $Q$ has bounded total rank:
550	\begin{equation*}
551	\sum_a \mathrm{rank}(Q_a) \leq d.
552	\end{equation*}
553	\end{lemma}
554	\begin{proof}
555	Let $\{R_a\}$ be the set of projective matrices given by \Cref{lem:projective-non-measurement}.
556	For each $a$, let $r_a$ be the rank of $R_a$.
557	Let $r = \sum_a r_a$.
558	If $r \leq d$, then the lemma is trivially satisfied by taking $Q$ to be~$R$ and applying \Cref{lem:projective-non-measurement}.
559	Henceforth, we will assume that $r > d$.
560	We want to reduce~$r$ so that it is at most~$d$.
561	Fortunately, it is already not too much larger than~$d$:
562	\begin{equation}\label{eq:bound-on-r}
563	r
564	= \sum_{a} r_a
565	= \sum_{a} \trace(R_a)
566	= \trace(R)
567	\leq (1 + 2\sqrt{\zeta}) \cdot \trace(I)
568	= (1+2\sqrt{\zeta}) \cdot d.
569	\end{equation}
570	Let $\ket{v_{a, 1}}, \ldots, \ket{v_{a, r_a}}$ be an orthonormal basis for the range of $R_a$, so that
571	\begin{equation*}
572	R_a = \sum_{i=1}^{r_a} \ket{v_{a, i}}\bra{v_{a,i}}.
573	\end{equation*}
574	To reduce~$r$,
575	we will throw out those $\ket{v_{a,i}}$'s whose overlap with $\ket{\psi}$ is small.
576	For each $a$ and $1 \leq i \leq r_a$, we denote the overlap of $\ket{v_{a,i}}$ and $\ket{\psi}$ by
577	\begin{equation*}
578	o_{a, i} = \bra{\psi} \cdot (\ket{v_{a,i}}\bra {v_{a,i}} \ot I) \cdot\ket{\psi}.
579	\end{equation*}
580	The total overlap is given by
581	\begin{align}
582	\sum_a \sum_{i=1}^{r_a} o_{a, i}
583	&= \sum_a \sum_{i=1}^{r_a} \bra{\psi} \cdot (\ket{v_{a,i}}\bra {v_{a,i}} \ot I) \cdot\ket{\psi}\nonumber\\
584	&= \sum_a \bra{\psi} R_a \ot I \ket{\psi}\nonumber\\
585	&= \bra{\psi} R \ot I \ket{\psi}\nonumber\\
586	&\leq (1+2\sqrt{\zeta}) \cdot \bra{\psi} I \ot I \ket{\psi}\nonumber\\
587	&= 1+2\sqrt{\zeta}.\label{eq:total-overlap}
588	\end{align}
589	Now we define $\mathsf{Large}$ to be the set of large overlaps:
590	\begin{equation*}
591	\mathsf{Large} = \{(a, i) \mid \text{$o_{a, i}$ is among the~$d$ largest of the $o_{b, j}$'s}\},
592	\end{equation*}
593	where we break ties arbitrarily,
594	and we define $\mathsf{Small}$ to be the set containing the remaining $(a, i)$'s.
595	We note that $\mathsf{Large}$ is well-defined and has size~$d$ because $r > d$.
596	Hence, \Cref{eq:bound-on-r} implies that
597	\begin{equation}\label{eq:size-of-small-is-small}
598	|\mathsf{Small}|
599	= r - |\mathsf{Large}| 
600	= r - d
601	\leq (1 + 2\sqrt{\zeta}) \cdot d - d
602	= 2\sqrt{\zeta} \cdot d
603	\leq 2\sqrt{\zeta} \cdot r.
604	\end{equation}
605	Thus, the small $(a,i)$'s have small total overlap:
606	\begin{align}
607	\sum_{(a, i) \in \mathsf{Small}} o_{a, i}
608	\leq \frac{|\mathsf{Small}|}{r} \sum_{a, i} o_{a,i}
609	&\leq 2\sqrt{\zeta} \cdot \sum_{a, i} o_{a,i} \tag{by \Cref{eq:size-of-small-is-small}}\\
610	&\leq 2\sqrt{\zeta} \cdot (1+2\sqrt{\zeta}) \tag{by \Cref{eq:total-overlap}}\\
611	& \leq 4\sqrt{\zeta}, \label{eq:small-overlaps}
612	\end{align}
613	where the final step uses the assumption that $\zeta \leq 1/4$ from \Cref{eq:assumption-on-zeta}.
614	
615	For each~$a$ we let $\mathsf{Large}_a$ to be set of $i$'s such that $(a,i)$ is contained in $\mathsf{Large}$,
616	and we define $\mathsf{Small}_a$ similarly.
617	We define the matrix
618	\begin{equation*}
619	Q_a = \sum_{i\in \mathsf{Large}_a} \ket{v_{a, i}}\bra{v_{a,i}}.
620	\end{equation*}
621	Then clearly
622	\begin{equation*}
623	\sum_a \mathrm{rank}(Q_a)
624	= \sum_a |\mathsf{Large}_a|
625	= |\mathsf{Large}|
626	\leq d.
627	\end{equation*}
628	We can compute the difference
629	\begin{equation*}
630	R_a - Q_a
631	= \sum_{i=1}^{r_a} \ket{v_{a, i}}\bra{v_{a,i}} - \sum_{i \in \mathsf{Large}_a}  \ket{v_{a, i}}\bra{v_{a,i}}
632	= \sum_{i\in \mathsf{Small}_a} \ket{v_{a, i}}\bra{v_{a,i}}.
633	\end{equation*}
634	This is a projective Hermitian matrix, which implies that $Q_a \leq R_a$.
635	As a result,
636	\begin{equation*}
637	Q = \sum_a Q_a \leq \sum_a R_a = R \leq (1+2\sqrt{\zeta}) \cdot I.
638	\end{equation*}
639	In addition,
640	\begin{align*}
641	\sum_a \Vert (R_a - Q_a) \ot I \ket{\psi} \Vert^2
642	&= \sum_a \bra{\psi}(R_a - Q_a)^2 \ot I \ket{\psi}\\
643	&= \sum_a \bra{\psi}(R_a - Q_a)\ot I \ket{\psi} \tag{because $R_a - Q_a$ is a projector}\\
644	&= \sum_a \sum_{i \in \mathsf{Small}_a} \bra{\psi} \cdot (\ket{v_{a,i}}\bra {v_{a,i}} \ot I) \cdot\ket{\psi}\\
645	&= \sum_a \sum_{i \in \mathsf{Small}_a} o_{a, i}\\
646	&\leq 4\sqrt{\zeta}. \tag{by \Cref{eq:small-overlaps}}
647	\end{align*}
648	This means that
649	\begin{equation*}
650	R_a \ot I \approx_{4\sqrt{\zeta}} Q_a \ot I.
651	\end{equation*}
652	Since we know that $A_a \ot I \approx_{2\sqrt{\zeta}} R_a \ot I$ by \Cref{lem:projective-non-measurement},
653	\Cref{prop:triangle-inequality-for-approx_delta} implies that
654	\begin{equation*}
655	A_a \ot I \approx_{12\sqrt{\zeta}} Q_a \ot I.
656	\end{equation*}
657	
658	This completes the proof.
659	\end{proof}
660	
661	Henceforth, we let $Q = \{Q_a\}$ be the set of projective matrices given by \Cref{lem:projective-low-rank-sum}.
662	We now derive a few properties of~$Q$ that follow as a consequence of \Cref{lem:projective-low-rank-sum}.
663	To begin, we show that~$Q$ is almost as complete as~$A$.
664	
665	\begin{lemma}[Completeness of~$Q$]\label{lem:Q-completeness}
666	\begin{equation*}
667	\bra{\psi} Q \otimes I \ket{\psi}
668	\geq 1 - 11 \zeta^{1/4}.
669	\end{equation*}
670	\end{lemma}
671	\begin{proof}
672	To begin, we claim that
673	\begin{align}
674	\bra{\psi} Q \otimes I \ket{\psi}
675	& = \sum_a \bra{\psi} Q_a \otimes I \ket{\psi}\nonumber\\
676	& = \sum_a \bra{\psi} (Q_a)^2 \otimes I \ket{\psi}\tag{because the $Q_a$'s are projective}\\
677	& \approx_{5 \zeta^{1/4}} \sum_a \bra{\psi} (Q_a \cdot A_a) \otimes I \ket{\psi}. \label{eq:Q-for-an-A}
678	\end{align}
679	To show this, we bound the magnitude of the difference.
680	\begin{align*}
681	&\Big|\sum_a \bra{\psi} (Q_a \otimes I) \cdot ((Q_a - A_a) \otimes I) \ket{\psi}\Big|\\
682	\leq~&\sqrt{\sum_a\bra{\psi} (Q_a)^2 \otimes I \ket{\psi}}
683		\cdot \sqrt{\sum_a \bra{\psi} (Q_a - A_a)^2 \otimes I \ket{\psi}}\\
684	\leq~&  \sqrt{1+2\sqrt{\zeta}} \cdot \sqrt{12\sqrt{\zeta}} \tag{by \Cref{lem:projective-low-rank-sum}}\\
685	\leq~& \sqrt{2} \cdot \sqrt{12\sqrt{\zeta}},
686	\end{align*}
687	where the last line uses the assumption that $\zeta \leq 1/4$ from \Cref{eq:assumption-on-zeta}.
688	Next, we claim that
689	\begin{equation}\label{eq:another-Q-for-A}
690	\eqref{eq:Q-for-an-A}
691	= \sum_a \bra{\psi} (Q_a \cdot A_a) \otimes I \ket{\psi}
692	\approx_{4 \zeta^{1/4}} \sum_a \bra{\psi} (A_a)^2 \otimes I \ket{\psi}.
693	\end{equation}
694	To show this, we bound the magnitude of the difference.
695	\begin{align*}
696	&\Big|\sum_a \bra{\psi} ((Q_a - A_a) \otimes I) \cdot (A_a \otimes I) \ket{\psi}\Big|\\
697	\leq~&\sqrt{\sum_a \bra{\psi} (Q_a - A_a)^2 \otimes I \ket{\psi}}
698		\cdot \sqrt{\sum_a\bra{\psi} (A_a)^2 \otimes I \ket{\psi}}\\
699	\leq~& \sqrt{12 \sqrt{\zeta}} \cdot 1. \tag{by \Cref{lem:projective-low-rank-sum}}
700	\end{align*}
701	In conclusion,
702	\begin{align*}
703	\bra{\psi} Q \otimes I \ket{\psi}
704	& \geq \sum_a \bra{\psi} (A_a)^2 \otimes I \ket{\psi} - 9 \zeta^{1/4} \tag{by \Cref{eq:Q-for-an-A,eq:another-Q-for-A}}\\
705	& \geq \sum_a \bra{\psi} A_a \otimes I \ket{\psi} - 2\zeta - 9\zeta^{1/4} \tag{by \Cref{eq:A-looks-projective}}\\
706	& \geq \bra{\psi} A \otimes I \ket{\psi} - 11 \zeta^{1/4} \nonumber\\
707	& = 1 - 11 \zeta^{1/4}.
708	\end{align*}
709	This completes the proof.
710	\end{proof}
711	
712	We will also need the following bound on the completeness of the \emph{square root} of~$Q$.
713	Note that such a bound follows trivially from \Cref{lem:Q-completeness}
714	when~$Q$ is a sub-measurement because $\sqrt{Q} \geq Q$ when $Q \leq I$.
715	
716	\begin{lemma}[Completeness of~$\sqrt{Q}$]\label{lem:sqrt-Q-completeness}
717	\begin{equation*}
718	\bra{\psi} \sqrt{Q} \otimes I \ket{\psi}
719	\geq 1 - 12 \zeta^{1/4}.
720	\end{equation*}
721	\end{lemma}
722	\begin{proof}
723	Let $Q = \sum_i \nu_i \ket{u_i} \bra{u_i}$ be the eigendecomposition of~$Q$.
724	Then because $Q \leq (1 + 2\sqrt{\zeta}) \cdot I$, each eigenvalue $\nu_i$ is at most $1+2\sqrt{\zeta}$.
725	Thus,
726	\begin{equation*}
727	\sqrt{Q}
728	= \sum_i \sqrt{\nu_i} \ket{u_i}\bra{u_i}
729	\geq \frac{1}{\sqrt{1 + 2\sqrt{\zeta}}} \cdot \sum_i \nu_i \ket{u_i}\bra{u_i}
730	= \frac{1}{\sqrt{1 + 2\sqrt{\zeta}}} \cdot Q.
731	\end{equation*}
732	We note that
733	\begin{equation*}
734	\frac{1}{\sqrt{1 + 2\sqrt{\zeta}}}
735	\geq \frac{1}{\sqrt{1 + 2\sqrt{\zeta} + \zeta}}
736	= \frac{1}{1 + \sqrt{\zeta}}
737	= \frac{1}{1 + \sqrt{\zeta}} \cdot \Big(\frac{1-\sqrt{\zeta}}{1-\sqrt{\zeta}}\Big)
738	= \frac{1-\sqrt{\zeta}}{1 - \zeta}
739	\geq 1 - \sqrt{\zeta}.
740	\end{equation*}
741	Hence, $\sqrt{Q} \geq (1-\sqrt{\zeta}) \cdot Q$.
742	As a result, \Cref{lem:Q-completeness} implies that
743	\begin{equation*}
744	\bra{\psi} \sqrt{Q} \otimes I \ket{\psi}
745	\geq (1-\sqrt{\zeta}) \cdot\bra{\psi} Q \otimes I \ket{\psi}
746	\geq (1-\sqrt{\zeta}) \cdot \left(1 - 11 \zeta^{1/4}\right)
747	\geq 1 -\sqrt{\zeta} - 11 \zeta^{1/4}.
748	\end{equation*}
749	This concludes the proof.
750	\end{proof}
751	
752	Finally, we show the following lemma,
753	which quantifies a sense in which~$Q$ is ``almost projective".
754	
755	\begin{lemma}[$Q$ is almost projective]\label{lem:q-almost-projective}
756	\begin{equation*}
757	\sum_a (Q_a \cdot Q  \cdot Q_a - Q_a) \leq  4\sqrt{\zeta} \cdot I.
758	\end{equation*}
759	\end{lemma}
760	\begin{proof}
761	\Cref{lem:projective-low-rank-sum} implies that $Q \leq (1 + 2\sqrt{\zeta}) \cdot I$. As a result,
762	\begin{align*}
763	&\sum_a Q_a \cdot Q  \cdot Q_a - \sum_a Q_a\\
764	\leq ~&(1 + 2\sqrt{\zeta}) \cdot \sum_a Q_a \cdot I  \cdot Q_a - \sum_a Q_a \\
765	= ~&(1+2\sqrt{\zeta}) \cdot \sum_a  Q_a - \sum_a Q_a \tag{because the $Q_a$'s are projectors}\\
766	= ~&(1+2\sqrt{\zeta}) \cdot Q - Q\\
767	= ~& 2\sqrt{\zeta} \cdot Q\\
768	\leq~& 2\sqrt{\zeta} \cdot (1 + 2\sqrt{\zeta}) \cdot I\\
769	\leq~& 2 \sqrt{\zeta} \cdot 2 \cdot I. \tag{by \Cref{eq:assumption-on-zeta}}
770	\end{align*}
771	This completes the proof.
772	\end{proof}
773	
774	We now arrive at the most important definition in this proof,
775	which is a natural matrix decomposition for the $Q_a$ matrices.
776	
777	\begin{definition}[Matrix decomposition of~$Q_a$]
778	For each $a$, let $m_a$ be the rank of $Q_a$.
779	Let $\ket{v_{a, 1}}, \ldots, \ket{v_{a, m_a}}$ be an orthonormal basis for the range of $Q_a$, so that
780	\begin{equation*}
781	Q_a = \sum_{i=1}^{m_a} \ket{v_{a, i}}\bra{v_{a,i}}.
782	\end{equation*}
783	Let $m = \sum_a m_a$, and consider an orthonormal basis of $\C^m$ consisting of vectors $\ket{a, i}$ for each $a$ and $1 \leq i \leq m_a$.
784	For each $a$, define the matrix
785	\begin{equation*}
786	X_a = \sum_{i=1}^{m_a} \ket{a, i} \bra{v_{a, i}}.
787	\end{equation*}
788	In addition, define the matrix
789	\begin{equation}\label{eq:looks-like-singular-value-decomposition}
790	X = \sum_a X_a =  \sum_a \sum_{i=1}^{m_a} \ket{a, i} \bra{v_{a, i}}.
791	\end{equation}
792	Finally, we let $T = \{T_a\}$ be the projective measurement on $\C^m$ defined as
793	\begin{equation*}
794	T_a = \sum_{i=1}^{m_a} \ket{a, i}\bra{a, i}.
795	\end{equation*}
796	\end{definition}
797	
798	The next pair of lemmas will prove some basic properties of the~$X_a$ matrices.
799	
800	\begin{lemma}\label{lem:xa-t}
801	For each~$a$, $\displaystyle
802	X_a = T_a \cdot X.
803	$
804	\end{lemma}
805	\begin{proof}
806	This is a simple calculation:
807	\begin{equation*}
808	T_a \cdot X = \Big(\sum_i^{m_a} \ket{a, i} \bra{a,i}\Big)\cdot \Big( \sum_a \sum_{i=1}^{m_a}  \ket{a, i}\bra{v_{a, i}}\Big) 
809	= \sum_{i=1}^{m_a} \ket{a, i}\bra{v_{a, i}} = X_a.\qedhere
810	\end{equation*}
811	\end{proof}
812	
813	\begin{lemma}[$Q_a$ restated]\label{lem:qa-restated}
814	For each~$a$,
815	\begin{equation*}
816	Q_a = X^\dagger_a \cdot X_a = X^\dagger \cdot T_a \cdot X = X_a^\dagger \cdot X.
817	\end{equation*}
818	\end{lemma}
819	\begin{proof}
820	The first equality follows from
821	\begin{align*}
822	X_a^\dagger \cdot X_a
823	&= \Big(\sum_{i=1}^{m_a} \ket{v_{a, i}}\bra{a, i} \Big) \cdot \Big(\sum_{j=1}^{m_a} \ket{v_{a, j}}\bra{a, j} \Big)^\dagger\nonumber\\
824	&= \sum_{i, j=1}^{m_a} \ket{v_{a, i}}\bra{a, i} \cdot \ket{a, j} \bra{v_{a, j}}
825	= \sum_{i=1}^{m_a} \ket{v_{a,i}}\bra{v_{a,i}} = Q_a.
826	\end{align*}
827	The remaining equalities follow from \Cref{lem:xa-t} and the fact that~$T$ is a projective measurement.
828	\begin{equation*}
829	X_a^\dagger \cdot X_a
830	= (X^\dagger \cdot T_a) \cdot (T_a  \cdot X)
831	= X^\dagger \cdot T_a \cdot X = X_a^\dagger \cdot X.\qedhere
832	\end{equation*}
833	\end{proof}
834	
835	Now we introduce our main tool for studying~$X$, which is via its singular value decomposition.
836	
837	\begin{definition}[SVD of~$X$]
838	Let $X = U \cdot \Sigma_{m \times d} \cdot V^\dagger$ be the singular value decomposition (SVD) of~$X$.
839	Because~$X$ is an $m \times d$ matrix,
840	the definition of the SVD states that
841	$U$ is an $m \times m$ unitary matrix,
842	$V$ is a $d \times d$ unitary matrix,
843	and $\Sigma_{m\times d}$ is an $m \times d$ diagonal matrix
844	with nonnegative real numbers on its diagonal.
845	\end{definition}
846	
847	\begin{notation}
848	For positive integers $h$ and~$w$,
849	we will write $I_{h \times w}$ for the $h \times w$ matrix with $1$'s on its diagonal and $0$'s everywhere else.
850	
851	For integers $h, w \geq m$, we also write $\Sigma_{h \times w}$
852	for the $h \times w$ diagonal matrix whose diagonal agrees with $\Sigma_{m \times d}$'s;
853	namely, $(\Sigma_{h \times w})_{i, i} = (\Sigma_{m \times d})_{i,i}$ for all $1 \leq i \leq m$
854	and $(\Sigma_{h \times w})_{i, i} = 0$ for all $i > m$.
855	We note that because $\Sigma_{m \times d}$ is a real-valued diagonal matrix,
856	$(\Sigma_{h \times w})^\dagger = \Sigma_{w \times h}$.
857	\end{notation}
858	
859	With this definition,
860	we can give a helpful expression for the square of~$X$.
861	
862	\begin{lemma}[$X$ squared]\label{lem:X-squared}
863	\begin{equation*}
864	X \cdot X^\dagger = U  \cdot (\Sigma_{m \times m})^2 \cdot U^\dagger,
865	\quad
866	\text{and}
867	\quad
868	X^\dagger \cdot X = Q = V \cdot (\Sigma_{d \times d})^2 \cdot V^\dagger.
869	\end{equation*}
870	\end{lemma}
871	\begin{proof}
872	First,
873	\begin{align*}
874	X \cdot X^\dagger
875	&= (U  \cdot \Sigma_{m \times d} \cdot V^\dagger) \cdot (U  \cdot \Sigma_{m \times d} \cdot V^\dagger)^\dagger\\
876	&= U  \cdot \Sigma_{m \times d} \cdot V^\dagger \cdot V \cdot \Sigma_{d \times m} \cdot U^\dagger\\
877	&= U  \cdot \Sigma_{m \times d} \cdot I_{d \times d} \cdot \Sigma_{d \times m} \cdot U^\dagger \tag{because~$V$ is a $d \times d$ unitary}\\
878	&= U  \cdot (\Sigma_{m \times m})^2 \cdot U^\dagger \tag{because~$m \leq d$}.
879	\end{align*}
880	Second,
881	\begin{align*}
882	X^\dagger \cdot X
883	& = \sum_a X^\dagger \cdot T_a X  \tag{because~$T$ is a measurement}\\
884	&= \sum_a Q_a \tag{by \Cref{lem:qa-restated}}\\
885	&= Q.
886	\end{align*}
887	In addition, we can rewrite $X^\dagger \cdot X$ as
888	\begin{align*}
889	X^\dagger \cdot X
890	&= (U  \cdot \Sigma_{m \times d} \cdot V^\dagger)^\dagger \cdot (U  \cdot \Sigma_{m \times d} \cdot V^\dagger)\\
891	&= V \cdot \Sigma_{d \times m} \cdot U^\dagger \cdot U \cdot \Sigma_{m \times d} \cdot V^\dagger\\
892	&= V \cdot \Sigma_{d \times m} \cdot I_{m \times m} \cdot \Sigma_{m \times d} \cdot V^\dagger \tag{because~$U$ is an $m \times m$ unitary}\\
893	&= V \cdot (\Sigma_{d \times d})^2 \cdot V^\dagger.
894	\end{align*}
895	This completes the proof.
896	\end{proof}
